-- ============================================================================
-- H3: Process Safety: LOPA & SIL Determination joins the catalogue, the THIRD
-- course of the HSE module.
--
-- Catalogue row (module 'hse'; path_order 63, directly above H2 hygiene at 62
-- and H1 safetystats at 61; prereq_slug NULL, the carried-over answer "no hard
-- prerequisite inside a module"; school left at its default, as every
-- Facilities, Economics, Assurance and HSE course leaves it, so the fees are
-- the published school-level rows) plus the three capstones and their eighteen
-- graded fields, generated by tools/course-waves/lopa/gen_course.py from the
-- ENGINE'S OWN RUN (h3_capstone.mjs through the vendored engines/hse/lopa.js),
-- which it refuses to write unless fields.json carries exactly that run's
-- values and the tolerance gradedTolerance.js derives. Deep seeds are three
-- separate migrations; the go-live is a fifth and is HELD until a NextGen
-- production upload carries the route /dashboard/apps/lopa, because the 78
-- lessons, the teaching lab (lopaLab.js) and its three explorer panels ship in
-- the zip and not in this database.
--
-- THE ONE SENTENCE THE COURSE IS. A layer of protection analysis finds how much
-- risk reduction a scenario still needs, and a safety instrumented function has
-- to supply it, so the course teaches how much is missing (Associate), what a
-- SIF achieves (Professional) and how long its proof test may run and what the
-- engine does not know (Expert), and grades each tier on its own question with
-- numbers the engine returns.
--
-- THE ENGINE. engines/hse/lopa.js, vendored sha-identical with
-- petrolord-engines 6703c00. Nothing is invented: every frequency, probability,
-- IPL PFD, failure rate and TMEL is an input. An IPL is credited once and only
-- when flagged independent; an exact decade belongs to the lower SIL; the
-- full IEC 61508-6 Annex B form; two out of two carries no beta factor term; a
-- SIF is the series sum of its subsystems; the longest interval has explicit
-- states.
--
-- WHAT IS GRADED. AKPO (Associate) grades frequencies, a required RRF, a
-- required PFDavg, the loop through a proposed SIF and the exact decade; USAN
-- (Professional) grades three subsystem PFDavg values, the SIF's RRF, a
-- proposed 2oo2 and the loop back to the TMEL; YOHO (Expert) grades three
-- longest intervals, a PFDavg under imperfect proof test coverage, a coverage
-- floor and a SIF stretched to a longer interval. Every value is a return
-- value of the engine, and every prompt is rendered from the inputs the engine
-- was run on. Failure rates are illustrative, and each prompt says so.
--
-- All eighteen graded values were swept against every number the digest
-- prints and against every number handed to a learner in a prompt, at each
-- field's own shipped tolerance: 0 collisions, and 0 pairwise. No prompt
-- states another tier's graded value.
-- ============================================================================

insert into public.academy_apps (slug, name, module, path_order, status, prereq_slug)
values ('lopa', 'Process Safety: LOPA & SIL Determination', 'hse', 63, 'coming_soon', null)
on conflict (slug) do nothing;

insert into public.academy_capstones
    (app_slug, tier, cert_tier, dataset, title, prompt, fields)
values
(
  'lopa', 'beginner', 'associate',
  'AKPO, a gas plant LOPA worksheet of four scenarios',
  'How much risk reduction each row is missing',
  'AKPO, a gas plant, and four rows of its LOPA worksheet. Every frequency is per year, every probability and IPL PFD is a fraction, every row carries its TMEL, the tolerable mitigated event likelihood, as a frequency per year, and every IPL is credited only as its flags allow. SEPARATOR, overpressure of the inlet separator: initiating event frequency 0.37 per year; enabling condition ''high pressure well lined up to the separator'' 0.23; conditional modifiers ''ignition'' 0.42 and ''operator in the area'' 0.18; IPLs ''high pressure alarm with operator response'', IPL PFD 0.1, flagged independent and ''BPCS high pressure trip on the initiating controller'', IPL PFD 0.1, flagged not independent; TMEL 1e-5 per year. TANK, overfill of the condensate tank: initiating event frequency 0.83 per year; enabling conditions ''tank receiving from the separator'' 0.64 and ''rundown at the high rate'' 0.35; conditional modifier ''vapour cloud ignites'' 0.27; IPLs ''independent high level alarm with operator response'', IPL PFD 0.1, flagged independent and ''level transmitter shared with the control loop'', IPL PFD 0.1, flagged not independent; TMEL 1e-5 per year. COMPRESSOR, a compressor seal failure: initiating event frequency 0.19 per year; no enabling condition; conditional modifiers ''ignition'' 0.33, ''person present'' 0.52 and ''fatal injury'' 0.4; IPL ''gas detection with operator shutdown'', IPL PFD 0.1, flagged independent; TMEL 1e-5 per year; and a proposed SIF with a PFDavg of 0.0037. EXPORT, overpressure of the export pump: initiating event frequency 0.64 per year; enabling condition ''export pump on the high speed curve'' 0.625; conditional modifier ''release reaches the jetty'' 0.25; IPLs ''pressure relief to the closed drain'', IPL PFD 0.1, flagged independent and ''BPCS pump trip on the same controller'', IPL PFD 0.1, flagged not independent; TMEL 0.0001 per year. The site SIF catalogue holds one standard design per SIL band: SIL 1 at a PFDavg of 0.0273, SIL 2 at 0.00318 and SIL 3 at 0.000461. Report six values: the separator row''s unmitigated frequency per year; the separator row''s required risk reduction factor; the tank row''s mitigated frequency per year without a SIF; the tank row''s required PFDavg for its SIF; the compressor row''s mitigated frequency per year with its proposed SIF; and the export row''s mitigated frequency per year with the catalogue design for the SIL that row requires. The frequencies and the PFDavg to twelve decimals, the risk reduction factor to six decimals.',
  jsonb_build_array(
    jsonb_build_object('key','akpo_separator_unmitigated_frequency_per_yr', 'label','The separator row''s unmitigated frequency', 'unit','per year', 'expected',0.0064335600000000005, 'tol',5e-13),
    jsonb_build_object('key','akpo_separator_required_rrf', 'label','The separator row''s required risk reduction factor', 'unit','RRF', 'expected',64.3356, 'tol',5e-07),
    jsonb_build_object('key','akpo_tank_mitigated_frequency_without_sif_per_yr', 'label','The tank row''s mitigated frequency without a SIF', 'unit','per year', 'expected',0.00501984, 'tol',5e-13),
    jsonb_build_object('key','akpo_tank_required_sif_pfdavg', 'label','The tank row''s required PFDavg for its SIF', 'unit','PFDavg', 'expected',0.0019920953655893415, 'tol',5e-13),
    jsonb_build_object('key','akpo_compressor_mitigated_frequency_with_sif_per_yr', 'label','The compressor row''s mitigated frequency with its proposed SIF', 'unit','per year', 'expected',4.825392000000002e-06, 'tol',5e-13),
    jsonb_build_object('key','akpo_export_catalogue_sif_mitigated_frequency_per_yr', 'label','The export row''s mitigated frequency with the catalogue design for the SIL it requires', 'unit','per year', 'expected',0.0002730000000000001, 'tol',5e-13)
  )
),
(
  'lopa', 'intermediate', 'professional',
  'USAN, a high pressure trip SIF on a gas export line',
  'What the SIF achieves, subsystem by subsystem, and whether the row closes',
  'USAN, a high pressure trip on a gas export line. The failure rates below are illustrative, chosen for this exercise. Rates are per hour per channel and times are in hours. TRANSMITTERS: 2oo3, lambdaDU 6.3e-7 and lambdaDD 1.9e-6 per hour, proof tested every 8760 hours, MTTR 16 hours and MRT 16 hours, beta factor 0.06 and betaD 0.03. LOGIC SOLVER: a 1oo1 safety PLC, lambdaDU 4.6e-8 and lambdaDD 7.6e-7 per hour, proof tested every 8760 hours, MTTR 16 hours and MRT 16 hours. VALVES: two shutdown valves 1oo2, lambdaDU 2.4e-6 and lambdaDD 3e-7 per hour, proof tested every 8760 hours, MTTR 16 hours and MRT 16 hours, beta factor 0.1 and betaD 0.05. PROPOSED: a 2oo2 vote of the same transmitters, to cut spurious trips, on the same data sheet: lambdaDU 6.3e-7 and lambdaDD 1.9e-6 per hour, proof tested every 8760 hours, MTTR 16 hours and MRT 16 hours, carrying the beta factor 0.06 and betaD 0.03 of the 2oo3 set. THE LOPA ROW the SIF answers, overpressure of the export line: initiating event frequency 0.21 per year; enabling condition ''export compressor at full throughput'' 0.44; conditional modifier ''ignition'' 0.3; IPL ''pressure relief valve'', IPL PFD 0.01, flagged independent; TMEL, the tolerable mitigated event likelihood, 1e-6 per year. Use the IEC 61508-6 Annex B forms, with the mean repair time after a proof test (MRT) as stated. Report six values: the PFDavg of the 2oo3 transmitters; the PFDavg of the 1oo1 logic solver; the PFDavg of the 1oo2 valves; the risk reduction factor of the SIF built from those three subsystems; the PFDavg of the proposed 2oo2 transmitters; and the LOPA row''s mitigated frequency per year with the SIF. The PFDavg values and the frequency to twelve decimals, the risk reduction factor to six decimals.',
  jsonb_build_array(
    jsonb_build_object('key','usan_transmitters_2oo3_pfdavg', 'label','The PFDavg of the 2oo3 transmitters', 'unit','PFDavg', 'expected',0.00019634220842816946, 'tol',5e-13),
    jsonb_build_object('key','usan_logic_solver_1oo1_pfdavg', 'label','The PFDavg of the 1oo1 logic solver', 'unit','PFDavg', 'expected',0.000214376, 'tol',5e-13),
    jsonb_build_object('key','usan_valves_1oo2_pfdavg', 'label','The PFDavg of the 1oo2 valves', 'unit','PFDavg', 'expected',0.0011773445892821334, 'tol',5e-13),
    jsonb_build_object('key','usan_sif_rrf', 'label','The risk reduction factor of the SIF built from those three subsystems', 'unit','RRF', 'expected',629.6980204068868, 'tol',5e-07),
    jsonb_build_object('key','usan_proposed_2oo2_transmitters_pfdavg', 'label','The PFDavg of the proposed 2oo2 transmitters', 'unit','PFDavg', 'expected',0.00559976, 'tol',5e-13),
    jsonb_build_object('key','usan_mitigated_frequency_with_sif_per_yr', 'label','The LOPA row''s mitigated frequency with the SIF', 'unit','per year', 'expected',4.402110075252959e-07, 'tol',5e-13)
  )
),
(
  'lopa', 'advanced', 'expert',
  'YOHO, proof testing on a crude oil stabiliser',
  'How long each proof test may run, and where no interval helps',
  'YOHO, proof testing on a crude oil stabiliser. The failure rates below are illustrative, chosen for this exercise. Rates are per hour per channel, times are in hours, and a year is 8760 hours. VALVES: two shutdown valves 1oo2, lambdaDU 2.3e-6 per hour and no detected failures, MRT 48 hours, beta factor 0.07, proof tested every 8760 hours today; their allocated PFDavg budget is 0.0022. SINGLE VALVE: a 1oo1 valve, lambdaDU 7.8e-7 per hour and no detected failures, MRT 48 hours, proof tested every 8760 hours with a proof test coverage of 0.75; the failures the test misses are found only at overhaul, a lifetime of 105120 hours. Its target PFDavg is 0.0118. SINGLE TRANSMITTER: a 1oo1 transmitter, lambdaDU 6.1e-7 and lambdaDD 2.4e-6 per hour, MTTR 72 hours and MRT 72 hours, proof tested every 8760 hours with a proof test coverage of 0.6 and a lifetime of 131400 hours. Its target PFDavg is 0.003. THE FUNCTION: 2oo3 transmitters, lambdaDU 7.4e-7 and lambdaDD 1.3e-6 per hour, MTTR 24 hours and MRT 24 hours, beta factor 0.1 and betaD 0.05, allocated a PFDavg budget of 0.00015; a 1oo1 logic solver, lambdaDU 5.2e-8 and lambdaDD 9.1e-7 per hour, MTTR 24 hours and MRT 24 hours; and the 1oo2 valves above. Each is proof tested every 8760 hours today, and it is proposed to stretch every proof test interval in the function to 26280 hours. Report six values: the longest proof test interval of the 1oo2 valves that holds their budget, in hours; the PFDavg of the single valve at its present proof test interval; the longest proof test interval of the single valve that holds its target, in hours; the floor PFDavg of the single transmitter, below which no proof test interval brings it; the risk reduction factor of the function with every proof test interval stretched as proposed; and the longest proof test interval of the 2oo3 transmitters that holds their budget, in hours. The PFDavg values to twelve decimals, the hours and the risk reduction factor to six decimals.',
  jsonb_build_array(
    jsonb_build_object('key','yoho_valves_1oo2_max_interval_hours', 'label','The longest proof test interval of the 1oo2 valves that holds their budget', 'unit','hours', 'expected',19751.841538652778, 'tol',5e-07),
    jsonb_build_object('key','yoho_valve_1oo1_ptc_pfdavg', 'label','The PFDavg of the single valve at its present proof test interval', 'unit','PFDavg', 'expected',0.012848940000000001, 'tol',5e-13),
    jsonb_build_object('key','yoho_valve_1oo1_ptc_max_interval_hours', 'label','The longest proof test interval of the single valve that holds its target', 'unit','hours', 'expected',5173.880341878748, 'tol',5e-07),
    jsonb_build_object('key','yoho_transmitter_ptc_floor_pfdavg', 'label','The floor PFDavg of the single transmitter, below which no proof test interval brings it', 'unit','PFDavg', 'expected',0.01624752, 'tol',5e-13),
    jsonb_build_object('key','yoho_sif_rrf_at_three_year_interval', 'label','The risk reduction factor of the function with every proof test interval stretched', 'unit','RRF', 'expected',192.27709511406886, 'tol',5e-07),
    jsonb_build_object('key','yoho_transmitters_2oo3_max_interval_hours', 'label','The longest proof test interval of the 2oo3 transmitters that holds their budget', 'unit','hours', 'expected',3765.3355760909617, 'tol',5e-07)
  )
